$roots=@('http://localhost/','http://127.0.0.1/','http://localhost:80/','http://127.0.0.1:8000/','http://localhost:8000/'); foreach ($u in $roots) { Write-Host "--- Testing $u ---"; try { $r=Invoke-WebRequest -Uri $u -UseBasicParsing -TimeoutSec 3 -ErrorAction Stop; Write-Host "STATUS: $($r.StatusCode)"; Write-Host $r.Content } catch { Write-Host "FAILED: $($_.Exception.Message)" } }